import Link from 'next/link';

export default function Forbidden() {
  return (
    <main
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        backgroundColor: '#fafafa',
        color: '#111',
        padding: '2rem',
        textAlign: 'center',
      }}
    >
      <div
        style={{
          backgroundColor: '#fff',
          border: '1px solid #eaeaea',
          borderRadius: '8px',
          padding: '3rem',
          maxWidth: '480px',
          width: '100%',
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.08)',
        }}
      >
        <p
          style={{
            fontSize: '4rem',
            margin: '0 0 0.5rem',
            lineHeight: 1,
          }}
        >
          403
        </p>
        <h1
          style={{
            fontSize: '1.5rem',
            fontWeight: 600,
            margin: '0 0 1rem',
          }}
        >
          Forbidden
        </h1>
        <p
          style={{
            color: '#666',
            fontSize: '1rem',
            lineHeight: 1.6,
            margin: '0 0 2rem',
          }}
        >
          You do not have permission to access this page. Administrator
          privileges are required.
        </p>
        <Link
          href="/"
          style={{
            display: 'inline-block',
            padding: '0.6rem 1.5rem',
            backgroundColor: '#111',
            color: '#fff',
            borderRadius: '6px',
            textDecoration: 'none',
            fontSize: '0.9rem',
            fontWeight: 500,
          }}
        >
          Go back home
        </Link>
      </div>
    </main>
  );
}

